/* 0.2 The ten-minute presentation · v2 on the D2 template (brief G 0.2, R10 checklist §4).
   Sixteen slides, each with one headline, one figure or visual and speaker notes in both languages.
   Navigation: buttons, numbered slide buttons, and the keyboard (← → Home End; Page Up/Down and Space inside the deck;
   N shows or hides the notes). Every model number is read from window.MODEL, follows the funding switch, shows the
   selected option only (B5) and is wrapped in AB.numHTML where it differs between the options (C6.4).
   Package prices come from window.AB_BOXPRICE (shell/boxprice.js), 12-month plan unless a slide says otherwise.
   The downside cash low and the use-of-funds labels come from window.AB_S6 (6.1). Faceless images only (D-1). */
(function(){
'use strict';
const A=()=>window.AB,T=(e,s)=>A().T(e,s),E=s=>A().E(s),L=(e,s)=>E(T(e,s)),N=(k,v,f)=>A().numHTML('s02-'+k,v,f),S6=()=>window.AB_S6;
const BP=(slug,o)=>(window.AB_BOXPRICE&&window.AB_BOXPRICE(slug,o||{plan:'m12'}))||null;
const sw=()=>window.AFYA_LANG==='sw';
const nf=n=>Math.round(n).toLocaleString('en-US');
const tsh=n=>'TSh '+nf(n);
const tshM=n=>S6()?S6().tshM(n):'TSh '+Math.round(n/1e6)+(sw()?' milioni':'M');
const pct=n=>Math.round(n*1000)/10+'%';
const GATE_N=300;                                        /* D-20 pre-sale gate */
const BUDGET=[30,40,40,35,40,35,35,40,35,35,35,40,35,45,40,40]; /* seconds per slide, 600 in all */

/* ---------- sources (numbered as cited) ---------- */
const SRC=()=>[
 {t:T('Mayige et al., Tanzania Journal of Health Research 27(2), 2026: hypertension among adults aged 18–69, 2023 National STEPS survey (23.1%)','Mayige na wenzake, Tanzania Journal of Health Research 27(2), 2026: shinikizo la juu la damu kwa watu wazima wa miaka 18–69, utafiti wa kitaifa wa STEPS 2023 (23.1%)'),u:'https://nhrdr.nimr.or.tz/records/209',chk:'9 Nov 2026'},
 {t:T('WHO, United Republic of Tanzania hypertension country profile (2012 STEPS survey, adults aged 25–64: aware 17.6%, treated 8.3%, controlled 2.2%)','WHO, wasifu wa nchi kuhusu shinikizo la juu la damu, Jamhuri ya Muungano wa Tanzania (utafiti wa STEPS 2012, watu wazima wa miaka 25–64: wanaojua 17.6%, wanaotibiwa 8.3%, waliodhibiti 2.2%)'),u:'https://cdn.who.int/media/docs/default-source/country-profiles/hypertension/tza_en.pdf',chk:'9 Nov 2026'},
 {t:T('NBS: 2022 Population and Housing Census, Housing Condition, Household Amenities and Assets: 1,537,293 private households in Dar es Salaam','NBS: Sensa ya Watu na Makazi 2022, Hali ya Makazi, Huduma na Mali za Kaya: kaya binafsi 1,537,293 Dar es Salaam'),u:'https://www.nbs.go.tz/uploads/statistics/documents/en-1764003000-Housing Condition, Household Amenities and Assets.pdf'},
 {t:T('City Population, NBS census counts: Dar es Salaam region 5,383,728 people (2022)','City Population, sensa za NBS: mkoa wa Dar es Salaam watu 5,383,728 (2022)'),u:'https://www.citypopulation.de/en/tanzania/admin/07',chk:'10 Nov 2026'},
 {t:T('TanzaniaInvest, 14 June 2026: TCRA telecom statistics, quarter ending March 2026 (80.98 million mobile-money accounts)','TanzaniaInvest, 14 Juni 2026: takwimu za mawasiliano za TCRA, robo inayoishia Machi 2026 (akaunti milioni 80.98 za pesa kwa simu)'),u:'https://tanzaniainvest.com/telecoms/tcra-telecom-stats-q1-2026'},
 {t:T('The Citizen, 27 May 2026: diaspora remittances hit Sh3.3 trillion (2024/25 financial year)','The Citizen, 27 Mei 2026: fedha za diaspora zafikia Sh trilioni 3.3 (mwaka wa fedha 2024/25)'),u:'https://www.thecitizen.co.tz/tanzania/diaspora/diaspora-remittances-hit-sh3-3-trillion-as-tanzania-deepens-global-engagement-5473984'},
 {t:T('Afya Basics box price lists, section 3.5: every item with a sourced shelf price, priced with the member pricing rule (3% / 6% / 9% below shelf, packing and delivery included)','Orodha za bei za maboksi ya Afya Basics, sehemu 3.5: kila kitu na bei ya rafu yenye chanzo, kwa kanuni ya bei ya mwanachama (3% / 6% / 9% chini ya bei ya rafu, ufungashaji na usafirishaji ukiwemo)'),u:''},
 {t:T('Afya Basics financial model v1.2, base and downside cases (planning estimates; follows the funding option selected)','Modeli ya fedha ya Afya Basics v1.2, hali ya msingi na hali mbaya (makadirio ya mipango; inafuata chaguo la mtaji lililochaguliwa)'),u:''}];
const cite=n=>`<sup><a href="#abSrc" class="ab-cite" aria-label="${L('Source','Chanzo')} ${n}">${n}</a></sup>`;
const tag=k=>`<span class="ab-est">${k==='target'?L('target','lengo'):L('model','modeli')}</span>`;

/* ---------- the line-up (names per D-3; brief B16) ---------- */
const LINEUP=[['mama-mjamzito','Mama Mjamzito','Pregnancy','Ujauzito'],['mama-na-mtoto','Mama na Mtoto','Mother and baby, to 3 years','Mama na mtoto, hadi miaka 3'],['afya-shule','Afya Shule','Children 4 to 12','Watoto wa miaka 4 hadi 12'],['binti','Binti','Teenage girls','Wasichana wa umri wa balehe'],['kijana','Kijana','Teenage boys','Wavulana wa umri wa balehe'],['afya-glow','Afya Glow','Women 20 to 59','Wanawake wa miaka 20 hadi 59'],['afya-men','Afya Men','Men 20 to 59','Wanaume wa miaka 20 hadi 59'],['bibi-na-babu','Bibi na Babu','Older adults, 60+','Wazee, miaka 60+'],
 ['sukari','Sukari','Diabetes','Kisukari'],['presha','Presha','High blood pressure','Shinikizo la juu la damu'],['figo','Figo','Kidney care','Huduma ya figo'],['kupona','Kupona','Recovery','Kupona'],['huduma-ya-kwanza','Huduma ya Kwanza','First aid at home','Huduma ya kwanza nyumbani'],['nyumbani','Nyumbani','Home essentials','Mahitaji ya nyumbani'],['afya-siku','Afya Siku','Period care','Huduma ya hedhi'],['afya-kazini','Afya Kazini','Offices','Ofisi'],['afya-biashara','Afya Biashara','Small businesses','Biashara ndogo'],['afya-hoteli','Afya Hoteli','Hotels and guest houses','Hoteli na nyumba za wageni']];
/* six illustrative households (section 1.4) and the box each one takes */
const HOUSE=[['A new mother and her baby','Mama mpya na mtoto wake','mama-na-mtoto'],['An expectant mother','Mama mjamzito','mama-mjamzito'],['A father living with diabetes','Baba anayeishi na kisukari','sukari'],['A daughter caring for her mother','Binti anayemhudumia mama yake','bibi-na-babu'],['A man recovering after surgery','Mwanamume anayepona baada ya upasuaji','kupona'],['A son abroad paying for his mother’s box','Mwana aliye nje ya nchi anayelipia boksi la mama yake','presha']];
const nameOf=slug=>(LINEUP.find(x=>x[0]===slug)||[slug,slug])[1];
const priceLine=(r,plan)=>r?`${tsh(r.from)} <span class="s02-per">${L(r.per.en,r.per.sw)}${plan?' · '+plan:''}</span>`:`<span class="ab-mute">${L('not priced','haijapewa bei')}</span>`;

/* ---------- numbers, all from MODEL ---------- */
function nums(){const M=window.MODEL,I=M.inputs,r=M.get('base'),rd=M.get('down'),U=S6();
 const cs=U?U.cashPath(I,r):null,csd=U?U.cashPath(I,rd):null,dsc=(I.scenarios||{}).down||{demand:1,cost:1};
 const yr=r.years,last=yr[yr.length-1];
 return {M,I,r,rd,lean:A().isLean(),seed:I.seed,own:I.ownership,cs,csd,dDem:Math.round((1-dsc.demand)*100),dCost:Math.round((dsc.cost-1)*100),
  y1rev:r.y1.revenue,y1loss:-r.y1.profit,be:r.breakeven_month,mem12:r.months[11].members,mem3:r.months[2].members,last,yr,
  t3:U?U.t3Rule(I):null,area:I.store.area_m2}}

/* ---------- visuals (inline SVG, tokens only) ---------- */
function cascadeSVG(){const rows=[[100,'Adults with high blood pressure','Watu wazima wenye shinikizo la juu la damu'],[17.6,'Knew they had it','Walijua wanalo'],[8.3,'Were on treatment','Walikuwa kwenye matibabu'],[2.2,'Had it under control','Walikuwa wamelidhibiti']];
 const W=560,x0=4,bw=W-120;return `<svg class="s02-svg" viewBox="0 0 ${W} 200" role="img" aria-label="${L('Of every 100 adults with high blood pressure in 2012: 17.6 knew, 8.3 were treated, 2.2 had it under control','Kati ya kila watu wazima 100 wenye shinikizo la juu la damu mwaka 2012: 17.6 walijua, 8.3 walitibiwa, 2.2 walikuwa wamelidhibiti')}">
 ${rows.map((x,i)=>{const y=12+i*46,w=Math.max(3,bw*x[0]/100);return `<text x="${x0}" y="${y}" font-size="14" fill="var(--mute)">${L(x[1],x[2])}</text><rect x="${x0}" y="${y+6}" width="${w}" height="18" fill="${i===3?'var(--gold)':'var(--green)'}"/><text x="${x0+w+8}" y="${y+21}" font-size="15" font-weight="600" fill="var(--gold)">${x[0]}</text>`}).join('')}
 <line x1="${x0}" y1="196" x2="${x0+bw}" y2="196" stroke="var(--line)"/></svg>`}

function funnelSVG(n){const hh=1537293,need=hh*0.5,aff=need*0.3;
 const rows=[[hh,T('Households in Dar es Salaam, 2022 census','Kaya Dar es Salaam, sensa ya 2022'),T('NBS','NBS')],[need,T('With a monthly health need: about half','Zenye hitaji la afya la kila mwezi: takriban nusu'),T('estimate','makadirio')],[aff,T('Able to pay for a box: about 3 in 10 of those','Zinazoweza kulipia boksi: takriban 3 kati ya 10 ya hizo'),T('estimate','makadirio')],[n.mem12,T('Afya Box members by month 12','Wanachama wa Afya Box ifikapo mwezi 12'),T('model','modeli')]];
 const W=560,wd=[540,400,270,140];
 return `<svg class="s02-svg" viewBox="0 0 ${W} 296" role="img" aria-label="${L('A funnel, not to scale: Dar es Salaam households, those with a monthly health need, those able to pay, and the members planned by month 12','Faneli, si kwa uwiano halisi: kaya za Dar es Salaam, zenye hitaji la afya la kila mwezi, zinazoweza kulipia, na wanachama waliopangwa ifikapo mwezi 12')}">
 ${rows.map((x,i)=>{const y=4+i*72,w=wd[i],xx=(W-w)/2;return `<rect x="${xx}" y="${y}" width="${w}" height="34" fill="${i===3?'var(--gold)':i?'var(--green-deep)':'var(--surface)'}" stroke="${i===3?'var(--gold)':'var(--green-edge)'}"/>
  <text x="${W/2}" y="${y+23}" text-anchor="middle" font-size="17" font-weight="600" fill="${i===3?'var(--bg)':'var(--gold)'}">${nf(x[0])}</text>
  <text x="${W/2}" y="${y+54}" text-anchor="middle" font-size="13" fill="var(--ink)">${E(x[1])} <tspan fill="var(--mute)">· ${E(x[2])}</tspan></text>`}).join('')}</svg>`}

function profitSVG(n){const m=n.r.months,W=560,H=230,pl=8,pb=26,pt=14;
 const pos=Math.max(0,...m.map(q=>q.profit)),neg=Math.max(0,...m.map(q=>-q.profit)),sc=(H-pt-pb)/((pos+neg)||1),zero=pt+pos*sc,bw=(W-pl*2)/m.length;
 return `<svg class="s02-svg" viewBox="0 0 ${W} ${H}" role="img" aria-label="${L('Monthly operating result of the store in year 1, base case: losses in the first months, then the first monthly profit','Matokeo ya uendeshaji ya duka kila mwezi mwaka wa 1, hali ya msingi: hasara miezi ya mwanzo, kisha faida ya kwanza ya mwezi')}">
 ${m.map((q,i)=>{const h=Math.abs(q.profit)*sc,x=pl+i*bw+3,y=q.profit>=0?zero-h:zero;return `<rect x="${x.toFixed(1)}" y="${y.toFixed(1)}" width="${(bw-6).toFixed(1)}" height="${Math.max(1,h).toFixed(1)}" fill="${q.profit>=0?'var(--gold)':'var(--green)'}"/><text x="${(x+(bw-6)/2).toFixed(1)}" y="${H-8}" text-anchor="middle" font-size="12" fill="var(--mute)">${q.m}</text>`}).join('')}
 <line x1="${pl}" y1="${zero.toFixed(1)}" x2="${W-pl}" y2="${zero.toFixed(1)}" stroke="var(--line)"/></svg>`}

function revSVG(n){const y=n.yr,W=560,H=240,pl=8,pb=26,pt=26,max=Math.max(...y.map(x=>x.revenue)),bw=(W-pl*2)/y.length;
 return `<svg class="s02-svg" viewBox="0 0 ${W} ${H}" role="img" aria-label="${L('Revenue by year for twelve years with the number of stores above each bar, base case','Mapato kwa mwaka kwa miaka kumi na miwili pamoja na idadi ya maduka juu ya kila nguzo, hali ya msingi')}">
 ${y.map((q,i)=>{const h=Math.max(2,(H-pt-pb)*q.revenue/max),x=pl+i*bw+4,yy=H-pb-h;return `<rect x="${x.toFixed(1)}" y="${yy.toFixed(1)}" width="${(bw-8).toFixed(1)}" height="${h.toFixed(1)}" fill="${i===y.length-1?'var(--gold)':'var(--green)'}"/><text x="${(x+(bw-8)/2).toFixed(1)}" y="${(yy-6).toFixed(1)}" text-anchor="middle" font-size="12" fill="var(--ink)">${q.stores}</text><text x="${(x+(bw-8)/2).toFixed(1)}" y="${H-8}" text-anchor="middle" font-size="12" fill="var(--mute)">${q.year||i+1}</text>`}).join('')}
 <line x1="${pl}" y1="${H-pb}" x2="${W-pl}" y2="${H-pb}" stroke="var(--line)"/></svg>`}

const img=(src,w,h,en,swx)=>`<img class="s02-img" src="${src}" width="${w}" height="${h}" loading="lazy" alt="${L(en,swx)}">`;
const big=(v,l,s)=>`<div class="s02-big"><b>${v}</b><span>${l}</span>${s?`<small>${s}</small>`:''}</div>`;

/* ---------- the sixteen slides: h headline, v visual, n notes [en, sw], go the section to open ---------- */
function slides(n){const I=n.I,sd=n.seed,Tr=sd.tranches.map(t=>t*sd.amount),mm=BP('mama-na-mtoto'),D4=window.AFYA_D4,lean=n.lean;
 const opt=lean?T('start-small option','chaguo la kuanza kidogo'):T('flagship option','chaguo la duka kuu');
 const beTxt=n.be?T(`month ${n.be}`,`mwezi wa ${n.be}`):T('not within year 1','si ndani ya mwaka wa 1');
 const mmStage=mm?((window.AFYA_DATA.boxes['mama-na-mtoto'].stages.find(s=>s.key===mm.stage))||null):null;
 const mmPlans=['m1','m6','m12'].map(p=>BP('mama-na-mtoto',{plan:p,stage:mm&&mm.stage}));
 const pack=mmStage&&D4?D4.PACKING[mmStage.box_size]||0:0,deliv=D4?D4.DELIVERY:0;
 const ck=I.check,buys=ck.checks_day_m12*ck.check_to_purchase;
 const low=n.csd?n.csd.low:null,lowBase=n.cs?n.cs.low:null;
 const useRows=sd.use.map(u=>{const lab=/compliance/i.test(u[0])?{k:'comp',t:T('Launch compliance fees: licences, registrations, first-shipment certificate','Ada za uzingatiaji wa sheria wakati wa uzinduzi: leseni, usajili, cheti cha shehena ya kwanza')}:(S6()?S6().useLabel(u):{k:u[0],t:u[0]});return {k:lab.k||'x',t:lab.t,v:u[1]}});
 const useTot=useRows.reduce((t,x)=>t+x.v,0);
 const own=n.own,t3=n.t3;
 const ms=[T('On signing: lease advance, company and licences, fit-out starts','Wakati wa kusaini: kodi ya mapema, kampuni na leseni, ujenzi wa ndani unaanza'),
  T('Fit-out complete, TMDA and business licences in hand, stock ordered','Ujenzi wa ndani umekamilika, leseni za TMDA na za biashara ziko mkononi, bidhaa zimeagizwa'),
  t3?T(`Store open ${t3.open} months, ${t3.members} Afya Box members and a monthly loss below ${tshM(t3.loss)}`,`Duka limefunguliwa miezi ${t3.open}, wanachama ${t3.members} wa Afya Box na hasara ya mwezi chini ya ${tshM(t3.loss)}`):''];
 return [
 /* 1 */ {h:T('A health-essentials store in Dar es Salaam, with a monthly box that reaches the home before anything runs out.','Duka la bidhaa za afya jijini Dar es Salaam, na boksi la kila mwezi linalofika nyumbani kabla kitu hakijaisha.'),
  v:`${img('assets/boxes/mama-na-mtoto-closed.webp',1376,768,'The Afya Box for Mama na Mtoto: a green box with the lid lifted, gold lettering on the side','Afya Box ya Mama na Mtoto: boksi la kijani lenye mfuniko ulioinuliwa, maandishi ya dhahabu ubavuni')}
   ${mm?big(`${tsh(mm.from)} ${tag('model')}`,L(`Mama na Mtoto, ${mm.per.en} on the 12-month plan, against ${tsh(mm.shelf)} for the same goods at shelf price${''}`,`Mama na Mtoto, ${mm.per.sw} kwa mpango wa miezi 12, ukilinganisha na ${tsh(mm.shelf)} kwa bidhaa hizohizo kwa bei ya rafu`)+cite(7),L('Packing and delivery included','Ufungashaji na usafirishaji ukiwemo')):''}`,
  n:[`<p>Open with the one line on the slide, and nothing before it. Afya Basics is a health-essentials store in Dar es Salaam, and the Afya Box is a monthly delivery of what a household uses, chosen for one stage of life or one condition.</p><p>Then give the one fact. The Mama na Mtoto box costs ${tsh(mm?mm.from:0)} ${mm?mm.per.en:''} on the 12-month plan. The same goods cost ${tsh(mm?mm.shelf:0)} at shelf price, and packing and delivery are already inside the member price. Every item in that box has a sourced shelf price in section 3.5.</p><p>Say plainly that there are no sales yet. Every number in this presentation is a model figure or a target, and the slide says which.</p>`,
   `<p>Anza na mstari mmoja ulio kwenye slaidi, bila kitu kingine kabla yake. Afya Basics ni duka la bidhaa za afya jijini Dar es Salaam, na Afya Box ni mzigo wa kila mwezi wa vitu ambavyo kaya inatumia, uliochaguliwa kwa hatua moja ya maisha au hali moja ya afya.</p><p>Kisha toa ukweli mmoja. Boksi la Mama na Mtoto linagharimu ${tsh(mm?mm.from:0)} ${mm?mm.per.sw:''} kwa mpango wa miezi 12. Bidhaa hizohizo zinagharimu ${tsh(mm?mm.shelf:0)} kwa bei ya rafu, na ufungashaji na usafirishaji tayari viko ndani ya bei ya mwanachama. Kila kitu katika boksi hilo kina bei ya rafu yenye chanzo katika sehemu 3.5.</p><p>Sema wazi kwamba bado hakuna mauzo. Kila namba katika wasilisho hili ni ya modeli au ni lengo, na slaidi inaonyesha ni ipi.</p>`],go:'s3-5'},

 /* 2 */ {h:T('The plan in five numbers, and the ask.','Mpango kwa namba tano, na ombi.'),
  v:`<div class="s02-figs">
   ${big(`${N('y1rev',n.y1rev,'tshM')} ${tag('model')}`,L('Revenue in year 1','Mapato mwaka wa 1'),L('Store, boxes, online, services and business accounts, before tax','Duka, maboksi, mtandaoni, huduma na akaunti za biashara, kabla ya kodi'))}
   ${big(`${n.be?`${L('Month','Mwezi')} ${N('be',n.be,'int')}`:L('Not in year 1','Si mwaka wa 1')} ${tag('model')}`,L('Break-even month','Mwezi wa kufikia faida'),L('The first month in which the store’s monthly operating result is above zero','Mwezi wa kwanza ambapo matokeo ya uendeshaji ya duka kwa mwezi yako juu ya sifuri'))}
   ${big(`${N('mem12',n.mem12,'int')} ${tag('model')}`,L('Afya Box members by month 12','Wanachama wa Afya Box ifikapo mwezi 12'),L('Paying members only; pre-sale deposits not yet converted are not counted','Wanachama wanaolipa tu; amana za mauzo ya awali ambazo bado hazijageuka uanachama hazihesabiwi'))}
   ${big(`${N('y1loss',n.y1loss,'tshM')} ${tag('model')}`,L('Loss in year 1','Hasara mwaka wa 1'),L('Store level, before head office and tax','Ngazi ya duka, kabla ya ofisi kuu na kodi'))}
   ${big(`${N('seed',sd.amount,'tshM')}`,L('The seed asked for','Mtaji wa awali unaoombwa'),L(`${lean?'Start-small option':'Flagship option'}: released in three tranches against milestones`,`${lean?'Chaguo la kuanza kidogo':'Chaguo la duka kuu'}: unatolewa kwa awamu tatu kulingana na malengo`))}
  </div>`,
  n:[`<p>Put the facts before the story. These five numbers are the whole plan, for the ${opt} selected on this page.</p><p>Year-1 revenue is ${tshM(n.y1rev)}. The store first makes a monthly operating profit ${n.be?'in '+beTxt:beTxt}. By month 12 the plan has about ${nf(n.mem12)} paying Afya Box members; pre-sale deposits are not added to that count. Year 1 ends with a loss of about ${tshM(n.y1loss)} at store level.</p><p>The ask is ${tshM(sd.amount)}, released in three tranches, each against a milestone the investor can check. All five figures are model figures; none is a result yet. If someone asks why the other option is not shown, say that the funding switch shows one option at a time so that numbers are never mixed.</p>`,
   `<p>Weka ukweli kabla ya simulizi. Namba hizi tano ndizo mpango wote, kwa ${opt} lililochaguliwa katika ukurasa huu.</p><p>Mapato ya mwaka wa 1 ni ${tshM(n.y1rev)}. Duka linapata faida ya uendeshaji ya mwezi kwa mara ya kwanza ${n.be?`katika ${beTxt}`:beTxt}. Kufikia mwezi 12 mpango una takriban wanachama ${nf(n.mem12)} wa Afya Box wanaolipa; amana za mauzo ya awali haziongezwi kwenye idadi hiyo. Mwaka wa 1 unaisha na hasara ya takriban ${tshM(n.y1loss)} katika ngazi ya duka.</p><p>Ombi ni ${tshM(sd.amount)}, linalotolewa kwa awamu tatu, kila moja kulingana na lengo ambalo mwekezaji anaweza kulithibitisha. Takwimu zote tano ni za modeli; hakuna hata moja ambayo tayari ni matokeo. Mtu akiuliza kwa nini chaguo jingine halionyeshwi, eleza kwamba kitufe cha chaguo la mtaji kinaonyesha chaguo moja kwa wakati ili namba zisichanganywe.</p>`],go:'s6-3'},

 /* 3 */ {h:T('Care has moved home. Shopping for it has not.','Huduma ya afya imehamia nyumbani. Ununuzi wake bado haujahamia.'),
  v:`${big(`23.1%${cite(1)}`,L('of Tanzanian adults aged 18–69 had raised blood pressure in 2023','ya watu wazima wa Tanzania wa miaka 18–69 walikuwa na shinikizo la juu la damu mwaka 2023'))}${cascadeSVG()}<p class="s02-cap">${L('Of every 100 adults with high blood pressure, 2012 national survey, the last to measure control','Kati ya kila watu wazima 100 wenye shinikizo la juu la damu, utafiti wa kitaifa wa 2012, wa mwisho kupima udhibiti')}${cite(2)}</p>`,
  n:[`<p>This slide answers the first question: is the problem real? Almost one adult in four had raised blood pressure in the 2023 national survey. In the 2012 survey, the last that measured control, about 18 in every 100 people with high blood pressure knew they had it, and about 2 had it under control.</p><p>Be clear about the years: the prevalence figure is from 2023, the awareness and control figures from 2012.</p><p>The point for the business is where the care happens. Blood pressure, diabetes, a new baby and an ageing parent are all managed at home, every day, with products that run out. The shops that supply families were built for one-off purchases: they keep no record, do not deliver and run out of stock.</p>`,
   `<p>Slaidi hii inajibu swali la kwanza: je, tatizo ni la kweli? Karibu mtu mzima mmoja kati ya wanne alikuwa na shinikizo la juu la damu katika utafiti wa kitaifa wa 2023. Katika utafiti wa 2012, wa mwisho kupima udhibiti, takriban watu 18 kati ya kila 100 wenye shinikizo la juu la damu walijua wanalo, na takriban 2 walikuwa wamelidhibiti.</p><p>Kuwa wazi kuhusu miaka: kiwango cha ugonjwa ni cha 2023, na takwimu za kujua na kudhibiti ni za 2012.</p><p>Hoja kwa biashara ni mahali huduma inapofanyika. Shinikizo la damu, kisukari, mtoto mchanga na mzazi anayezeeka vyote vinasimamiwa nyumbani, kila siku, kwa bidhaa zinazoisha. Maduka yanayohudumia familia yalijengwa kwa manunuzi ya mara moja: hayaweki kumbukumbu, hayaleti nyumbani na bidhaa huisha.</p>`],go:'s1-2'},

 /* 4 */ {h:T('Six households, one repeating need.','Kaya sita, hitaji moja linalojirudia.'),
  v:`<div class="ab-tw"><table class="ab-t s02-t"><thead><tr><th>${L('Household (illustrative)','Kaya (ya mfano)')}</th><th>${L('Box','Boksi')}</th><th class="ab-n">${L('From','Kuanzia')}</th></tr></thead><tbody>
   ${HOUSE.map(h=>{const once=h[2]==='kupona',r=BP(h[2],{plan:once?'m1':'m12'});return `<tr><td>${L(h[0],h[1])}</td><td>${E(nameOf(h[2]))}</td><td class="ab-n">${priceLine(r,once?T('1-month plan','mpango wa mwezi 1'):'')}</td></tr>`}).join('')}
  </tbody></table></div><p class="s02-cap">${L('12-month plan unless shown; Kupona is a six-week course of two boxes.','Mpango wa miezi 12 isipoonyeshwa vinginevyo; Kupona ni mpango wa wiki sita wenye maboksi mawili.')}${cite(7)}</p>`,
  n:[`<p>Now make the customer concrete. These six households are illustrative, built from national data on who has these needs, not from interviews; say so.</p><p>Pick two and tell their month in a sentence each. The new mother walks to three shops for nappies, wipes and lotion; with Afya her box arrives before the nappies run out, and the size changes with one swap. The father with diabetes needs strips that fit his meter; his meter is saved to his account, so the right strips always come.</p><p>Point at the prices: each is the lowest repeat box on the 12-month plan, with its delivery rhythm. A box that comes every three months carries three months of goods. Medicines are never in the box price: they come from the licensed partner pharmacy.</p>`,
   `<p>Sasa mfanye mteja aonekane halisi. Kaya hizi sita ni za mfano, zimejengwa kutoka takwimu za kitaifa kuhusu nani ana mahitaji haya, si kutoka mahojiano; lisema hilo.</p><p>Chagua mbili na usimulie mwezi wao kwa sentensi moja kila mmoja. Mama mpya anatembea maduka matatu kununua nepi, vitambaa vya mtoto na losheni; kwa Afya boksi lake linafika kabla nepi hazijaisha, na saizi inabadilishwa kwa kubadilisha mara moja. Baba mwenye kisukari anahitaji vipande vinavyoendana na mashine yake; aina ya mashine yake imehifadhiwa kwenye akaunti yake, hivyo vipande sahihi vinakuja kila mara.</p><p>Onyesha bei: kila moja ni boksi la kurudia la bei ya chini kabisa kwa mpango wa miezi 12, pamoja na mdundo wake wa usafirishaji. Boksi linalokuja kila miezi mitatu linabeba bidhaa za miezi mitatu. Dawa hazimo kamwe kwenye bei ya boksi: zinatoka kwa famasia mshirika yenye leseni.</p>`],go:'s1-4',wide:1},

 /* 5 */ {h:T('One city is enough to start.','Jiji moja linatosha kuanza.'),
  v:`${funnelSVG(n)}<p class="s02-cap">${L('Not to scale. The two middle shares are the estimates used in section 1.3; the last step is the model’s member count.','Si kwa uwiano halisi. Viwango viwili vya kati ni makadirio yanayotumika katika sehemu 1.3; hatua ya mwisho ni idadi ya wanachama ya modeli.')}${cite(3)}${cite(8)}</p>`,
  n:[`<p>The point of this slide is proportion. Investors worry that a new brand needs a large share of the market to survive; show them the opposite.</p><p>Dar es Salaam had 1,537,293 households in the 2022 census. If about half have a monthly health need, and about three in ten of those can pay for a box, that is roughly 230,000 homes; both shares are estimates. The plan needs about ${nf(n.mem12)} members by month 12, a small fraction of one percent of those homes.</p><p>Note what the slide does not do: it does not multiply the market by a price to make a revenue figure. Revenue in the model is built from visitors, members who join and members who leave. The full working is in section 1.3.</p>`,
   `<p>Hoja ya slaidi hii ni uwiano. Wawekezaji wanahofia kwamba chapa mpya inahitaji sehemu kubwa ya soko ili iishi; waonyeshe kinyume chake.</p><p>Dar es Salaam ilikuwa na kaya 1,537,293 katika sensa ya 2022. Kama takriban nusu zina hitaji la afya la kila mwezi, na takriban tatu kati ya kumi ya hizo zinaweza kulipia boksi, hizo ni takriban kaya 230,000; viwango vyote viwili ni makadirio. Mpango unahitaji takriban wanachama ${nf(n.mem12)} kufikia mwezi 12, sehemu ndogo ya asilimia moja ya kaya hizo.</p><p>Angalia kile ambacho slaidi haifanyi: haizidishi soko kwa bei ili kupata mapato. Mapato katika modeli yanajengwa kutoka kwa wateja wanaotembelea, wanachama wanaojiunga na wanachama wanaoondoka. Hesabu kamili iko katika sehemu 1.3.</p>`],go:'s1-3'},

 /* 6 */ {h:T('Four shifts make this the moment.','Mabadiliko manne yanafanya huu kuwa wakati sahihi.'),
  v:`<div class="s02-figs">${big(`23.1%${cite(1)}`,L('adults with raised blood pressure, 2023','watu wazima wenye shinikizo la juu la damu, 2023'))}${big(`${L('80.98M','milioni 80.98')}${cite(5)}`,L('mobile-money accounts, March 2026','akaunti za pesa kwa simu, Machi 2026'))}${big(`5,383,728${cite(4)}`,L('people in Dar es Salaam region, 2022','watu katika mkoa wa Dar es Salaam, 2022'))}${big(`${L('TSh 3.3T','TSh trilioni 3.3')}${cite(6)}`,L('sent home by the diaspora, 2024/25','zilizotumwa nyumbani na diaspora, 2024/25'))}</div>`,
  n:[`<p>Answer “why now?” with four shifts that are already happening; the plan waits for none of them.</p><p>First, chronic care has moved home: almost one adult in four has raised blood pressure. Second, mobile money is how Tanzanians pay: about 81 million mobile-money accounts in March 2026, so a monthly payment request on the phone is normal. Afya accepts every wallet, card and cash and depends on no single operator.</p><p>Third, Dar es Salaam is large and dense, 5.38 million people in 2022, which makes delivery on a fixed day affordable. Fourth, Tanzanians abroad sent home about TSh 3.3 trillion in 2024/25. Some of that already pays for a parent’s care; a box paid by card from abroad makes it visible.</p>`,
   `<p>Jibu swali la “kwa nini sasa?” kwa mabadiliko manne yanayotokea tayari; mpango haungoji hata moja.</p><p>Kwanza, huduma ya magonjwa ya muda mrefu imehamia nyumbani: karibu mtu mzima mmoja kati ya wanne ana shinikizo la juu la damu. Pili, pesa kwa simu ndiyo njia Watanzania wanalipa: takriban akaunti milioni 81 za pesa kwa simu mwezi Machi 2026, hivyo ombi la malipo la kila mwezi kwenye simu ni jambo la kawaida. Afya inapokea kila pochi ya simu, kadi na taslimu na haitegemei kampuni moja.</p><p>Tatu, Dar es Salaam ni kubwa na lina watu wengi, watu milioni 5.38 mwaka 2022, jambo linalofanya usafirishaji kwa siku maalum kuwa nafuu. Nne, Watanzania walioko nje walituma nyumbani takriban TSh trilioni 3.3 mwaka 2024/25. Sehemu ya fedha hizo tayari inalipia huduma ya mzazi; boksi linalolipwa kwa kadi kutoka nje linaifanya ionekane.</p>`],go:'s1-5'},

 /* 7 */ {h:T('One store, one membership, one app.','Duka moja, uanachama mmoja, programu moja.'),
  v:`${img('img/interior.webp',2400,1340,'The planned store interior: oak shelves, a counter with screens above it and a waiting area, with no people','Ndani ya duka lililopangwa: rafu za mbao, kaunta yenye skrini juu yake na eneo la kusubiri, bila watu')}<ul class="s02-list"><li><b>${L('The store','Duka')}</b> ${L(`${n.area} m², organised by need, a free Afya Check at the door`,`m² ${n.area}, limepangwa kwa mahitaji, Afya Check ya bure mlangoni`)}</li><li><b>${L('The Afya Box','Afya Box')}</b> ${L('18 boxes, on 1-, 6- or 12-month plans','maboksi 18, kwa mipango ya mwezi 1, miezi 6 au miezi 12')}</li><li><b>${L('The app and WhatsApp','Programu na WhatsApp')}</b> ${L('reorder, pay by mobile money, pay from abroad','agiza tena, lipa kwa pesa ya simu, lipa ukiwa nje ya nchi')}</li></ul>`,
  n:[`<p>This is the reveal. Pause on the picture, which shows the planned interior, before speaking.</p><p>Say the positioning in one line: Afya Basics is a health-essentials store with a membership at its core. It is not a pharmacy counter and not a supermarket aisle. The ${n.area} m² store is organised by life situation, carries registered products only, and offers a free Afya Check at the entrance.</p><p>The Afya Box is the core: eighteen boxes, each built item by item for one stage of life or one need, on a 1-, 6- or 12-month plan. The app and WhatsApp make reordering quick and let family abroad pay. Medicines are sold only by the licensed partner pharmacy, at its own counter and on its own receipt.</p>`,
   `<p>Huu ndio ufunuo. Simama kidogo kwenye picha, inayoonyesha ndani ya duka lililopangwa, kabla ya kuzungumza.</p><p>Eleza nafasi ya chapa kwa mstari mmoja: Afya Basics ni duka la bidhaa za afya lenye uanachama kama kiini chake. Si kaunta ya famasia wala si njia ya bidhaa za supamaketi. Duka la m² ${n.area} limepangwa kwa hali za maisha, lina bidhaa zilizosajiliwa pekee, na linatoa Afya Check ya bure mlangoni.</p><p>Afya Box ndiyo kiini: maboksi kumi na nane, kila moja limejengwa kitu kwa kitu kwa hatua moja ya maisha au hitaji moja, kwa mpango wa mwezi 1, miezi 6 au miezi 12. Programu na WhatsApp zinafanya kuagiza tena kuwe haraka na zinawawezesha ndugu walioko nje kulipa. Dawa zinauzwa na famasia mshirika yenye leseni pekee, kwenye kaunta yake na kwa risiti yake.</p>`],go:'s3-1'},

 /* 8 */ {h:T('Eighteen boxes, each with a sourced price.','Maboksi kumi na nane, kila moja na bei yenye chanzo.'),
  v:`<div class="s02-lu">${LINEUP.map(b=>{const r=BP(b[0]);return `<div><b>${E(b[1])}</b><span>${L(b[2],b[3])}</span><em>${r?`${L('from','kuanzia')} ${tsh(r.from)}`:L('not priced','haijapewa bei')}</em>${r?`<small>${L(r.per.en,r.per.sw)}</small>`:''}</div>`}).join('')}</div><p class="s02-cap">${L('Lowest repeat box on the 12-month plan, default brands, packing and delivery included.','Boksi la kurudia la bei ya chini kabisa kwa mpango wa miezi 12, chapa za kawaida, ufungashaji na usafirishaji ukiwemo.')}${cite(7)}</p>`,
  n:[`<p>Show the breadth without reading every box. Eight boxes follow the stages of life, from pregnancy to older age; seven follow a condition or a need, such as diabetes, blood pressure, kidney care, recovery and first aid; three serve offices, small businesses and hotels.</p><p>Every price on this slide is computed the same way: the shelf value of the goods inside, less the member saving for the plan, rounded to the nearest TSh 500 and never above the shelf value. Packing and delivery are inside the price, not added at the door.</p><p>Each box shows its delivery rhythm. Some come monthly; others every two or three months, because a small box sent every month could not cover its own packing and delivery.</p>`,
   `<p>Onyesha upana bila kusoma kila boksi. Maboksi manane yanafuata hatua za maisha, kuanzia ujauzito hadi uzee; saba yanafuata hali au hitaji, kama kisukari, shinikizo la damu, huduma ya figo, kupona na huduma ya kwanza; matatu yanahudumia ofisi, biashara ndogo na hoteli.</p><p>Kila bei katika slaidi hii inakokotolewa kwa njia ileile: thamani ya rafu ya bidhaa zilizomo, ukitoa punguzo la mwanachama kwa mpango husika, ikizungushwa hadi TSh 500 iliyo karibu na isiyozidi thamani ya rafu. Ufungashaji na usafirishaji viko ndani ya bei, haviongezwi mlangoni.</p><p>Kila boksi linaonyesha mdundo wake wa usafirishaji. Mengine yanakuja kila mwezi; mengine kila miezi miwili au mitatu, kwa sababu boksi dogo linalotumwa kila mwezi lisingeweza kulipia ufungashaji na usafirishaji wake.</p>`],go:'s3-5'},

 /* 9 */ {h:T('One box, from shelf value to member price.','Boksi moja, kutoka thamani ya rafu hadi bei ya mwanachama.'),
  v:mm?`<div class="ab-tw"><table class="ab-t s02-t"><tbody>
   <tr><td>${L('Shelf value of the goods (Afya’s own shelf prices)','Thamani ya rafu ya bidhaa (bei za rafu za Afya)')}</td><td class="ab-n">${tsh(mm.shelf)}</td></tr>
   <tr><td>${L(`Member saving on the 12-month plan, ${Math.round((D4?D4.SAVING.m12:0)*100)}%, rounded to TSh 500`,`Punguzo la mwanachama kwa mpango wa miezi 12, ${Math.round((D4?D4.SAVING.m12:0)*100)}%, likizungushwa hadi TSh 500`)}</td><td class="ab-n">− ${tsh(mm.shelf-mm.from)}</td></tr>
   <tr><td><b>${L('Member price, packing and delivery included','Bei ya mwanachama, ufungashaji na usafirishaji ukiwemo')}</b></td><td class="ab-n">${tsh(mm.from)}</td></tr>
   <tr><td class="ab-mute">${L('Inside that price: packing at landed cost and delivery','Ndani ya bei hiyo: ufungashaji kwa gharama halisi na usafirishaji')}</td><td class="ab-n">${tsh(pack+deliv)}</td></tr></tbody></table></div>
   <p class="s02-rule">${L('Members never pay more than the shelf price, and every cost is recovered in the price.','Wanachama hawalipi kamwe zaidi ya bei ya rafu, na kila gharama inarudishwa ndani ya bei.')}</p><p class="s02-cap">${L(`Mama na Mtoto, ${mmStage?mmStage.label.en:''}, default brands`,`Mama na Mtoto, ${mmStage?mmStage.label.sw:''}, chapa za kawaida`)}${cite(7)}</p>`:'',
  n:[`<p>Walk one box from top to bottom. This is the Mama na Mtoto box for a child in the second year, the repeat month, with the default brand for every item.</p><p>The goods inside are worth ${tsh(mm?mm.shelf:0)} at Afya’s own shelf prices. On the 12-month plan the member pays ${tsh(mm?mm.from:0)}, about ${Math.round((D4?D4.SAVING.m12:0)*100)}% less, rounded to the nearest TSh 500. Packing at landed cost and the delivery, together ${tsh(pack+deliv)}, are paid out of that price, not added to it.</p><p>Then read the rule on the slide word for word, because it is the principle of the whole business: members never pay more than the shelf price, and every cost is recovered in the price. Section 6.2 takes the same box down to its margin.</p>`,
   `<p>Pitia boksi moja kuanzia juu hadi chini. Hili ni boksi la Mama na Mtoto kwa mtoto wa mwaka wa pili, mwezi wa kurudia, kwa chapa ya kawaida kwa kila kitu.</p><p>Bidhaa zilizomo zina thamani ya ${tsh(mm?mm.shelf:0)} kwa bei za rafu za Afya zenyewe. Kwa mpango wa miezi 12 mwanachama analipa ${tsh(mm?mm.from:0)}, takriban ${Math.round((D4?D4.SAVING.m12:0)*100)}% chini, ikizungushwa hadi TSh 500 iliyo karibu. Ufungashaji kwa gharama halisi na usafirishaji, kwa pamoja ${tsh(pack+deliv)}, vinalipwa kutoka ndani ya bei hiyo, haviongezwi juu yake.</p><p>Kisha soma kanuni iliyo kwenye slaidi neno kwa neno, kwa sababu ndiyo msingi wa biashara nzima: wanachama hawalipi kamwe zaidi ya bei ya rafu, na kila gharama inarudishwa ndani ya bei. Sehemu 6.2 inapeleka boksi hilohilo hadi faida yake.</p>`],go:'s6-2'},

 /* 10 */ {h:T('A free check that starts the relationship.','Kipimo cha bure kinachoanzisha uhusiano.'),
  v:`${img('img/e1/kiosk.webp',2400,1350,'The Afya Check kiosk by the store entrance, with no one using it','Kioski cha Afya Check karibu na mlango wa duka, bila mtu anayekitumia')}<div class="s02-figs">${big(`${ck.free_readings.length}`,L(`free measurements in about ${ck.minutes} minutes`,`vipimo vya bure kwa takriban dakika ${ck.minutes}`))}${big(`${N('ck',ck.checks_day_m12,'int')} ${tag('model')}`,L('checks a day by month 12','vipimo kwa siku ifikapo mwezi 12'))}${big(`${N('ckb',buys,'int')} ${tag('model')}`,L(`purchases a day that start with a check (${Math.round(ck.check_to_purchase*100)}%)`,`manunuzi kwa siku yanayoanza na kipimo (${Math.round(ck.check_to_purchase*100)}%)`))}</div>`,
  n:[`<p>The Afya Check is the front door, and it is always free. The kiosk takes ${ck.free_readings.length} measurements in about ${ck.minutes} minutes, including blood pressure and pulse, weight and body mass index; results appear on screen and arrive by SMS.</p><p>Stress the rule: advisers explain a reading in plain words and refer the person to a clinic when a reading needs a doctor. Nobody is pressed to buy. The earlier slide showed that most people with high blood pressure do not know it; the check finds them.</p><p>Then the business logic, as model figures: about ${nf(ck.checks_day_m12)} checks a day by month 12, and if ${Math.round(ck.check_to_purchase*100)}% lead to a purchase, about ${nf(buys)} sales a day begin with a free service.</p>`,
   `<p>Afya Check ndio mlango wa mbele, na ni bure kila wakati. Kioski kinachukua vipimo ${ck.free_readings.length} kwa takriban dakika ${ck.minutes}, vikiwemo shinikizo la damu na mapigo ya moyo, uzito na kiwango cha uzito kwa urefu (BMI); majibu yanaonekana kwenye skrini na yanafika kwa SMS.</p><p>Sisitiza kanuni: washauri wanaeleza kipimo kwa lugha rahisi na wanampeleka mtu kliniki kipimo kinapohitaji daktari. Hakuna anayeshinikizwa kununua. Slaidi iliyotangulia ilionyesha kwamba watu wengi wenye shinikizo la juu la damu hawajui; kipimo kinawapata.</p><p>Kisha mantiki ya biashara, kama takwimu za modeli: takriban vipimo ${nf(ck.checks_day_m12)} kwa siku kufikia mwezi 12, na kama ${Math.round(ck.check_to_purchase*100)}% vinaleta ununuzi, takriban mauzo ${nf(buys)} kwa siku yanaanza na huduma ya bure.</p>`],go:'s3-3'},

 /* 11 */ {h:T('Membership is the core, not an add-on.','Uanachama ndio kiini, si nyongeza.'),
  v:`<div class="ab-tw"><table class="ab-t s02-t"><thead><tr><th>${L('Plan','Mpango')}</th><th class="ab-n">${L('Saving','Punguzo')}</th><th class="ab-n">${L('Mama na Mtoto, a month','Mama na Mtoto, kwa mwezi')}</th></tr></thead><tbody>
   ${[['m1','1 month','Mwezi 1'],['m6','6 months · Gold','Miezi 6 · Gold'],['m12','12 months · Platinum','Miezi 12 · Platinum']].map((p,i)=>`<tr><td>${L(p[1],p[2])}</td><td class="ab-n">${Math.round((D4?D4.SAVING[p[0]]:0)*100)}%</td><td class="ab-n">${mmPlans[i]?tsh(mmPlans[i].from):'—'}</td></tr>`).join('')}</tbody></table></div>
   <div class="s02-figs">${big(`${N('mem12b',n.mem12,'int')} ${tag('model')}`,L('members by month 12','wanachama ifikapo mwezi 12'))}${big(`${pct(I.members.monthly_churn)} ${tag('model')}`,L('of members assumed to leave each month','ya wanachama wanaodhaniwa kuondoka kila mwezi'))}</div>`,
  n:[`<p>This is the slide that turns a shop into a recurring business. Health needs repeat, so the box turns one-off shoppers into planned households.</p><p>There are three plans. On the monthly plan the member saves ${Math.round((D4?D4.SAVING.m1:0)*100)}% on the box goods; on the 6-month Gold plan ${Math.round((D4?D4.SAVING.m6:0)*100)}%; on the 12-month Platinum plan ${Math.round((D4?D4.SAVING.m12:0)*100)}%. Longer plans are paid once, up front. Members can swap brands until 12 days before month end, and receive reminders before every renewal.</p><p>The model plans about ${nf(n.mem12)} members by month 12 and assumes that ${pct(I.members.monthly_churn)} leave every month. That churn figure is an assumption, not a measurement: it is tested in the pre-sale and in the first months of trading.</p>`,
   `<p>Hii ndiyo slaidi inayogeuza duka kuwa biashara inayojirudia. Mahitaji ya afya yanajirudia, hivyo boksi linageuza wanunuzi wa mara moja kuwa kaya zenye mpango.</p><p>Kuna mipango mitatu. Kwa mpango wa kila mwezi mwanachama anaokoa ${Math.round((D4?D4.SAVING.m1:0)*100)}% kwenye bidhaa za boksi; kwa mpango wa Gold wa miezi 6, ${Math.round((D4?D4.SAVING.m6:0)*100)}%; kwa mpango wa Platinum wa miezi 12, ${Math.round((D4?D4.SAVING.m12:0)*100)}%. Mipango mirefu inalipwa mara moja, mapema. Wanachama wanaweza kubadilisha chapa hadi siku 12 kabla ya mwisho wa mwezi, na wanapata vikumbusho kabla ya kila kuhuisha.</p><p>Modeli inapanga takriban wanachama ${nf(n.mem12)} kufikia mwezi 12 na inadhani kwamba ${pct(I.members.monthly_churn)} wanaondoka kila mwezi. Kiwango hicho cha kuondoka ni dhana, si kipimo: kinajaribiwa katika mauzo ya awali na katika miezi ya kwanza ya biashara.</p>`],go:'s3-4'},

 /* 12 */ {h:T(`We expect to lose money in year 1, and we say how much.`,`Tunatarajia hasara mwaka wa 1, na tunasema ni kiasi gani.`),
  v:`${profitSVG(n)}<p class="s02-cap">${L('Store operating result by month, year 1, base case; green is a loss, gold a profit','Matokeo ya uendeshaji ya duka kwa mwezi, mwaka wa 1, hali ya msingi; kijani ni hasara, dhahabu ni faida')}${cite(8)}</p>
   <div class="s02-figs">${big(`${N('y1loss2',n.y1loss,'tshM')} ${tag('model')}`,L('loss in year 1','hasara mwaka wa 1'))}${big(`${n.be?`${L('Month','Mwezi')} ${N('be2',n.be,'int')}`:L('Not in year 1','Si mwaka wa 1')} ${tag('model')}`,L('first monthly profit','faida ya kwanza ya mwezi'))}</div>`,
  n:[`<p>Say the bad news in our own words, with the number. We expect the store to lose about ${tshM(n.y1loss)} in year 1, in the base case of the ${opt}. The first month with an operating profit is ${beTxt}.</p><p>Explain why. The first months carry the full rent, the full team and the launch, while members and walk-in visitors build up. The seed is sized for this: the line for operating losses and lease advances until break-even sits inside the use of funds, and a working-capital reserve sits beside it.</p><p>These are model figures at store level, before head office and tax. They are not results, and they will be replaced by the real monthly figures in the investor pack from the first month of trading.</p>`,
   `<p>Sema habari mbaya kwa maneno yetu wenyewe, pamoja na namba. Tunatarajia duka kupata hasara ya takriban ${tshM(n.y1loss)} mwaka wa 1, katika hali ya msingi ya ${opt}. Mwezi wa kwanza wenye faida ya uendeshaji ni ${n.be?beTxt:beTxt}.</p><p>Eleza sababu. Miezi ya mwanzo inabeba kodi kamili ya pango, timu kamili na uzinduzi, wakati wanachama na wateja wanaoingia dukani wanaongezeka polepole. Mtaji wa awali umepimwa kwa hili: mstari wa hasara za uendeshaji na kodi za mapema hadi kufikia faida uko ndani ya matumizi ya fedha, na akiba ya mtaji wa kazi iko kando yake.</p><p>Hizi ni takwimu za modeli katika ngazi ya duka, kabla ya ofisi kuu na kodi. Si matokeo, na zitabadilishwa na takwimu halisi za kila mwezi katika ripoti ya mwekezaji kuanzia mwezi wa kwanza wa biashara.</p>`],go:'s6-1'},

 /* 13 */ {h:T('From one store to a chain, store by store.','Kutoka duka moja hadi mtandao wa maduka, duka kwa duka.'),
  v:`${revSVG(n)}<p class="s02-cap">${L('Revenue by year (bars) and number of stores (above each bar), base case','Mapato kwa mwaka (nguzo) na idadi ya maduka (juu ya kila nguzo), hali ya msingi')}${cite(8)}</p>
   <div class="s02-figs">${big(`${tshM(n.last.revenue)} ${tag('target')}`,L(`revenue in year ${n.yr.length}`,`mapato mwaka wa ${n.yr.length}`))}${big(`${n.last.stores} ${tag('target')}`,L(`stores in year ${n.yr.length}`,`maduka mwaka wa ${n.yr.length}`))}</div>`,
  n:[`<p>Show how growth is built: one store at a time, each opened only when the one before it works. The model adds stores in a fixed sequence, first in Dar es Salaam, then in other Tanzanian cities, reaching ${n.last.stores} stores and about ${tshM(n.last.revenue)} of revenue in year ${n.yr.length}.</p><p>Call these what they are: targets in a planning model, not forecasts of results. Each new store is assumed to ramp up over three years to a mature level, with its own running costs and a share of head-office costs.</p><p>The point for this round is narrower: the seed pays for store 1 and the membership engine. Each later store is a separate decision, taken on the evidence of the first.</p>`,
   `<p>Onyesha jinsi ukuaji unavyojengwa: duka moja kwa wakati, kila moja likifunguliwa tu pale lililotangulia linapofanya kazi. Modeli inaongeza maduka kwa mpangilio maalum, kwanza Dar es Salaam, kisha katika miji mingine ya Tanzania, ikifikia maduka ${n.last.stores} na mapato ya takriban ${tshM(n.last.revenue)} mwaka wa ${n.yr.length}.</p><p>Zitaje kama zilivyo: malengo katika modeli ya mipango, si utabiri wa matokeo. Kila duka jipya linadhaniwa kukua kwa miaka mitatu hadi kiwango cha kukomaa, likiwa na gharama zake za uendeshaji na sehemu ya gharama za ofisi kuu.</p><p>Hoja kwa awamu hii ni finyu zaidi: mtaji wa awali unalipia duka la 1 na mfumo wa uanachama. Kila duka linalofuata ni uamuzi wake, unaofanywa kwa ushahidi wa duka la kwanza.</p>`],go:'s5-4'},

 /* 14 */ {h:low&&low.v<0?T('In the downside case cash falls below zero. Three answers are ready.','Katika hali mbaya fedha zinashuka chini ya sifuri. Majibu matatu yako tayari.'):T('Even in the downside case, cash stays above zero.','Hata katika hali mbaya, fedha zinabaki juu ya sifuri.'),
  v:`<div class="s02-figs">${low?big(`${N('dlow',Math.abs(low.v),'tshM')} ${L(low.v<0?'below zero':'above zero',low.v<0?'chini ya sifuri':'juu ya sifuri')} ${tag('model')}`,L(`lowest bank balance in the downside case, month ${low.i}`,`salio la chini kabisa la benki katika hali mbaya, mwezi ${low.i}`),L(`Demand ${n.dDem}% lower and running costs ${n.dCost}% higher than the base case`,`Mahitaji chini kwa ${n.dDem}% na gharama za uendeshaji juu kwa ${n.dCost}% kuliko hali ya msingi`)):''}${big(`${GATE_N} ${tag('target')}`,L('founding-member deposits before opening: the pre-sale gate','amana za wanachama waanzilishi kabla ya kufungua: kigezo cha mauzo ya awali'),lean?L(`Below ${GATE_N}: store 1 opens as this ${n.area} m² store`,`Chini ya ${GATE_N}: duka la 1 linafunguliwa kama duka hili la m² ${n.area}`):L(`${GATE_N} or more: the flagship goes ahead. Fewer: the plan falls back to start small`,`${GATE_N} au zaidi: duka kuu linaendelea. Chache zaidi: mpango unarudi kwenye kuanza kidogo`))}</div>
   <p class="s02-cap">${L('If cash falls further, three answers are planned:','Fedha zikishuka zaidi, majibu matatu yamepangwa:')}</p><ol class="s02-list"><li>${L('More capital: a founder or investor bridge agreed before signing','Mtaji zaidi: mkopo wa muda kutoka kwa waanzilishi au mwekezaji unaokubaliwa kabla ya kusaini')}</li><li>${L('A bigger pre-sale: more members and deposits before opening','Mauzo makubwa zaidi ya awali: wanachama na amana zaidi kabla ya kufungua')}</li><li>${L('Cost cuts: marketing first, then hiring delayed','Kupunguza gharama: matangazo kwanza, kisha kuchelewesha ajira')}</li></ol>`,
  n:[`<p>Do not show only the good case. In the downside case, with demand ${n.dDem}% lower and running costs ${n.dCost}% higher, the lowest bank balance in year 1 is about ${low?tshM(Math.abs(low.v)):'—'} ${low&&low.v<0?'below zero':'above zero'}, in month ${low?low.i:'—'}, even with the tranches released at their milestones${lowBase?`; in the base case the lowest point is ${tshM(lowBase.v)}`:''}.</p><p>We have three answers ready: more capital through a bridge agreed before signing, a bigger pre-sale, and cost cuts, marketing first and then hiring.</p><p>Then the gate, which the founders set themselves. Before opening, Afya sells founding memberships with a refundable deposit. ${lean?`The option shown here is the store that opens if fewer than ${GATE_N} deposits come in.`:`With ${GATE_N} deposits or more, the flagship goes ahead; with fewer, the plan falls back to the start-small store.`} The biggest early question, whether families will pay, becomes a count that can be checked before the larger store is committed.</p>`,
   `<p>Usionyeshe hali nzuri pekee. Katika hali mbaya, mahitaji yakiwa chini kwa ${n.dDem}% na gharama za uendeshaji juu kwa ${n.dCost}%, salio la chini kabisa la benki mwaka wa 1 ni takriban ${low?tshM(Math.abs(low.v)):'—'} ${low&&low.v<0?'chini ya sifuri':'juu ya sifuri'}, mwezi ${low?low.i:'—'}, hata awamu zikitolewa kulingana na malengo yake${lowBase?`; katika hali ya msingi kiwango cha chini kabisa ni ${tshM(lowBase.v)}`:''}.</p><p>Tuna majibu matatu tayari: mtaji zaidi kupitia mkopo wa muda unaokubaliwa kabla ya kusaini, mauzo makubwa zaidi ya awali, na kupunguza gharama, matangazo kwanza kisha ajira.</p><p>Kisha kigezo, ambacho waanzilishi wamekiweka wenyewe. Kabla ya kufungua, Afya inauza uanachama wa waanzilishi kwa amana inayorejeshwa. ${lean?`Chaguo linaloonyeshwa hapa ndilo duka linalofunguliwa amana zikiwa chini ya ${GATE_N}.`:`Amana ${GATE_N} au zaidi zikipatikana, duka kuu linaendelea; zikiwa chache, mpango unarudi kwenye duka la kuanza kidogo.`} Swali kubwa la mwanzo, kama familia zitalipa, linakuwa idadi inayoweza kuthibitishwa kabla duka kubwa halijaamuliwa.</p>`],go:'s6-3'},

 /* 15 */ {h:T('Five risks of our own, each with a trigger and an answer.','Hatari tano zetu wenyewe, kila moja na ishara na jibu.'),
  v:`<div class="ab-tw"><table class="ab-t s02-t"><thead><tr><th>${L('Risk','Hatari')}</th><th>${L('Trigger we watch','Ishara tunayoifuatilia')}</th><th>${L('Answer','Jibu')}</th></tr></thead><tbody>
   <tr><td>${L('Families do not commit before opening','Familia hazijitolei kabla ya kufungua')}</td><td>${L(`Fewer than ${GATE_N} founding deposits`,`Amana za waanzilishi chini ya ${GATE_N}`)}</td><td>${lean?L('This start-small store opens','Duka hili la kuanza kidogo linafunguliwa'):L('Fall back to the start-small store','Kurudi kwenye duka la kuanza kidogo')}</td></tr>
   <tr><td>${L('Members leave after the first months','Wanachama wanaondoka baada ya miezi ya kwanza')}</td><td>${L(`Churn above the ${pct(I.members.monthly_churn)} a month in the model`,`Kuondoka zaidi ya ${pct(I.members.monthly_churn)} kwa mwezi kama ilivyo kwenye modeli`)}</td><td>${L('Prepaid 6- and 12-month plans; upgrade offers at months 2 and 5','Mipango ya miezi 6 na 12 inayolipwa mapema; ofa za kupanda mpango mwezi wa 2 na wa 5')}</td></tr>
   <tr><td>${L('Growth is slower than planned','Ukuaji ni wa polepole kuliko ilivyopangwa')}</td><td>${L('Fewer members at month 3 than the model path','Wanachama wachache kufikia mwezi 3 kuliko njia ya modeli')} (${N('m3',n.mem3,'int')})</td><td>${L('A box offer after every free check; spend moved to the channels that bring visitors','Ofa ya boksi baada ya kila kipimo cha bure; matumizi yanahamishiwa njia zinazoleta wateja')}</td></tr>
   <tr><td>${L('Monthly payments fail','Malipo ya kila mwezi yanashindwa')}</td><td>${L('More than 1 request in 10 unpaid by day 22','Zaidi ya ombi 1 kati ya 10 halijalipwa kufikia siku ya 22')}</td><td>${L('Payment request on the phone with reminders on days 17 and 19, a second request and an adviser’s call','Ombi la malipo kwenye simu pamoja na vikumbusho siku ya 17 na 19, ombi la pili na simu ya mshauri')}</td></tr>
   <tr><td>${L('A medicine is handled by Afya','Dawa inashughulikiwa na Afya')}</td><td>${L('Any medicine on an Afya receipt','Dawa yoyote kwenye risiti ya Afya')}</td><td>${L('Medicines only through the licensed partner pharmacy, its licence checked every year','Dawa kupitia famasia mshirika yenye leseni pekee, leseni yake ikihakikiwa kila mwaka')}</td></tr></tbody></table></div>`,
  n:[`<p>Lead with the risks that belong to this business, not with country risks every company shares. Each one has a trigger we can see early and an answer agreed in advance.</p><p>The pre-sale gate settles the store size. Churn is watched against the ${pct(I.members.monthly_churn)} a month in the model, and the prepaid plans are the main defence. Growth is checked against the model path, about ${nf(n.mem3)} members at month 3. Mobile money has no standing-order service for subscriptions, so Afya sends a payment request each month, with reminders and an adviser’s call. And Afya never handles medicines: the licensed partner pharmacy sells them.</p><p>Section 7.3 ranks every risk by likelihood and impact, with the general risks grouped after these.</p>`,
   `<p>Anza na hatari zinazohusu biashara hii, si hatari za nchi ambazo kila kampuni inazo. Kila moja ina ishara tunayoweza kuiona mapema na jibu lililokubaliwa mapema.</p><p>Kigezo cha mauzo ya awali kinaamua ukubwa wa duka. Kuondoka kwa wanachama kunafuatiliwa dhidi ya ${pct(I.members.monthly_churn)} kwa mwezi kama ilivyo kwenye modeli, na mipango inayolipwa mapema ndiyo kinga kuu. Ukuaji unapimwa dhidi ya njia ya modeli, takriban wanachama ${nf(n.mem3)} kufikia mwezi 3. Pesa kwa simu haina huduma ya maagizo ya kudumu kwa usajili wa huduma, hivyo Afya inatuma ombi la malipo kila mwezi, pamoja na vikumbusho na simu ya mshauri. Na Afya haishughulikii dawa kamwe: famasia mshirika yenye leseni ndiyo inayoziuza.</p><p>Sehemu 7.3 inapanga kila hatari kwa uwezekano na athari, na hatari za jumla zimewekwa pamoja baada ya hizi.</p>`],go:'s7-3',wide:1},

 /* 16 */ {h:T(`${tshM(sd.amount)} to open store 1 and launch the box.`,`${tshM(sd.amount)} kufungua duka la 1 na kuzindua boksi.`).replace(tshM(sd.amount),N('seed2',sd.amount,'tshM')),
  v:`<div class="ab-tw"><table class="ab-t s02-t"><thead><tr><th>${L('Use of funds','Matumizi ya fedha')}</th><th class="ab-n">${L('Amount','Kiasi')}</th></tr></thead><tbody>
   ${useRows.map((u,i)=>`<tr><td>${E(u.t)}</td><td class="ab-n">${N('u'+i+'-'+u.k,u.v,'tsh')}</td></tr>`).join('')}
   <tr><td><b>${L('Total, equal to the seed','Jumla, sawa na mtaji wa awali')}</b></td><td class="ab-n"><b>${N('utot',useTot,'tsh')}</b></td></tr></tbody></table></div>
   <div class="ab-tw"><table class="ab-t s02-t"><thead><tr><th>${L('Tranche','Awamu')}</th><th>${L('Released when','Inatolewa lini')}</th><th class="ab-n">${L('Amount','Kiasi')}</th></tr></thead><tbody>
   ${Tr.map((v,i)=>`<tr><td>${i+1} · ${Math.round(sd.tranches[i]*100)}%</td><td>${E(ms[i]||'')} ${tag('target')}</td><td class="ab-n">${N('tr'+i,v,'tshM')}</td></tr>`).join('')}</tbody></table></div>
   <p class="s02-cap">${L(`After the round: founders ${Math.round(own.founders_after_seed*100)}%, seed investors ${Math.round(own.seed_investor_share*100)}%, option pool ${Math.round(own.option_pool*100)}%; the founders keep at least ${Math.round(own.founders_floor*100)}% for life.`,`Baada ya awamu: waanzilishi ${Math.round(own.founders_after_seed*100)}%, wawekezaji wa awali ${Math.round(own.seed_investor_share*100)}%, akiba ya hisa za wafanyakazi ${Math.round(own.option_pool*100)}%; waanzilishi wanabaki na angalau ${Math.round(own.founders_floor*100)}% maisha yote.`)}${cite(8)}</p>`,
  n:[`<p>Close with the ask, stated plainly. We are raising ${tshM(sd.amount)} for the ${opt}: the ${n.area} m² store, the opening stock, the launch, and the losses and lease advances until the store breaks even, with a reserve. The use of funds adds up to the seed to the shilling.</p><p>The money is not released at once. Tranche 1 comes on signing; tranche 2 when the fit-out is complete and the licences are in hand; tranche 3 when the store has been open ${t3?t3.open:3} months with ${t3?t3.members:100} Afya Box members and a monthly loss below ${t3?tshM(t3.loss):'the agreed limit'}. Each milestone has its evidence document.</p><p>After the round the seed investors hold ${Math.round(own.seed_investor_share*100)}% in this plan, subject to legal review. Then invite questions, and point to section 6.3 for the full terms and 7.5 for the data room.</p>`,
   `<p>Funga kwa ombi, likielezwa wazi. Tunatafuta ${tshM(sd.amount)} kwa ${opt}: duka la m² ${n.area}, bidhaa za kuanzia, uzinduzi, na hasara pamoja na kodi za mapema hadi duka lifikie faida, pamoja na akiba. Matumizi ya fedha yanajumlika sawasawa na mtaji wa awali hadi shilingi ya mwisho.</p><p>Fedha hazitolewi mara moja. Awamu ya 1 inakuja wakati wa kusaini; awamu ya 2 ujenzi wa ndani ukikamilika na leseni zikiwa mkononi; awamu ya 3 duka likiwa limefunguliwa miezi ${t3?t3.open:3} likiwa na wanachama ${t3?t3.members:100} wa Afya Box na hasara ya mwezi chini ya ${t3?tshM(t3.loss):'kiwango kilichokubaliwa'}. Kila lengo lina hati yake ya ushahidi.</p><p>Baada ya awamu wawekezaji wa awali wanamiliki ${Math.round(own.seed_investor_share*100)}% katika mpango huu, kwa kuzingatia ukaguzi wa kisheria. Kisha karibisha maswali, na uelekeze kwenye sehemu 6.3 kwa masharti kamili na 7.5 kwa chumba cha nyaraka.</p>`],go:'s6-3',wide:1}];
}

/* ---------- page ---------- */
const CSS=`
.s02 .s02-deck{margin-top:var(--s3);border:1px solid var(--line);background:var(--surface)}
.s02 .s02-deck:fullscreen{overflow:auto;background:var(--bg);padding:var(--s4)}
.s02 .s02-bar{display:flex;flex-wrap:wrap;gap:var(--s1) var(--s2);align-items:center;padding:var(--s2);border-bottom:1px solid var(--line)}
.s02 .s02-bar .s02-ct{color:var(--mute);font-size:var(--fs-cap);font-variant-numeric:tabular-nums;min-width:9ch}
.s02 .s02-bar .s02-sp{flex:1 1 auto}
.s02 .s02-slide{padding:var(--s4);min-height:460px}
.s02 .s02-slide[hidden]{display:none}
.s02 .s02-grid{display:grid;grid-template-columns:minmax(0,5fr) minmax(0,7fr);gap:var(--s4);align-items:start}
.s02 .s02-k{color:var(--gold);font-size:var(--fs-cap);font-variant-numeric:tabular-nums}
.s02 .s02-h{font-size:calc(var(--fs-sub) + 4px)!important;line-height:1.25!important;font-weight:600;margin:var(--s1) 0 0!important;max-width:24ch}
.s02 .s02-go{display:inline-block;margin-top:var(--s3);color:var(--mute);font-size:var(--fs-cap)}
.s02 .s02-v>*+*{margin-top:var(--s2)}
.s02 .s02-img{display:block;width:100%;height:auto}
.s02 .s02-svg{display:block;width:100%;height:auto;font-family:var(--font)}
.s02 .s02-big b .ab-est{font-size:var(--fs-cap);font-weight:400;color:var(--mute);margin-left:4px}
.s02 .s02-big b{display:block;color:var(--gold);font-size:var(--fs-sub);font-weight:600;font-variant-numeric:tabular-nums;line-height:1.25}
.s02 .s02-big>span{display:block;margin-top:4px;color:var(--ink);font-size:calc(var(--fs-body) - 1px)}
.s02 .s02-big>small{display:block;margin-top:4px;color:var(--mute);font-size:var(--fs-cap)}
.s02 .s02-figs{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:0;border-top:1px solid var(--line)}
.s02 .s02-figs>.s02-big{padding:var(--s2) var(--s2) var(--s2) 0;border-bottom:1px solid var(--line)}
.s02 .s02-cap{color:var(--mute);font-size:var(--fs-cap);max-width:var(--measure)}
.s02 .s02-per{display:block;color:var(--mute);font-size:var(--fs-cap);font-weight:400;white-space:normal}
.s02 .s02-wide{grid-template-columns:1fr;gap:var(--s3)}.s02 .s02-wide .s02-h{max-width:40ch}
.s02 .s02-v .ab-tw{margin-top:0}.s02 .s02-v>*+.ab-tw{margin-top:var(--s2)}
.s02 .s02-rule{border-left:2px solid var(--gold);padding-left:var(--s2);color:var(--ink)}
.s02 .s02-list{margin:0;padding-left:20px}.s02 .s02-list li+li{margin-top:6px}
.s02 .s02-lu{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:0;border-top:1px solid var(--line);border-left:1px solid var(--line)}
.s02 .s02-lu>div{padding:10px 12px;border-right:1px solid var(--line);border-bottom:1px solid var(--line);min-width:0}
.s02 .s02-lu b{display:block;font-weight:600;font-size:var(--fs-cap)}
.s02 .s02-lu span,.s02 .s02-lu small{display:block;color:var(--mute);font-size:var(--fs-cap);line-height:1.35}
.s02 .s02-lu em{display:block;font-style:normal;color:var(--gold);font-size:var(--fs-cap);font-weight:600;margin-top:4px;font-variant-numeric:tabular-nums}
.s02 .s02-notes{border-top:1px solid var(--line);padding:var(--s3) var(--s4);background:var(--bg)}
.s02 .s02-notes[hidden]{display:none}
.s02 .s02-notes h3{margin-top:0!important;color:var(--mute);font-size:var(--fs-cap)!important;font-weight:400!important}
.s02 .s02-notes p{max-width:var(--measure)}.s02 .s02-notes p+p{margin-top:var(--s1)}
.s02 .s02-dots{display:flex;flex-wrap:wrap;gap:6px;padding:var(--s2);border-top:1px solid var(--line)}
.s02 .s02-dots button{min-width:34px;min-height:34px;border:1px solid var(--line);background:none;color:var(--mute);font-size:var(--fs-cap);cursor:pointer;font-variant-numeric:tabular-nums}
.s02 .s02-dots button[aria-current="true"]{background:var(--green-deep);color:var(--ink);border-color:var(--green-edge)}
.s02 .s02-t td{vertical-align:top}.s02 .s02-t th.ab-n{text-align:right}
.s02 .ab-btn:disabled{opacity:.4;cursor:default}
.s02 .s02-outline td:first-child{color:var(--gold);font-variant-numeric:tabular-nums;white-space:nowrap}
.s02 .s02-all h3{margin-top:var(--s3)!important}
.s02 .s02-all p{max-width:var(--measure)}.s02 .s02-all p+p{margin-top:var(--s1)}
.s02 .ab-body>p+p{margin-top:var(--s2)}
@media (max-width:860px){.s02 .s02-grid{grid-template-columns:1fr;gap:var(--s3)}.s02 .s02-slide{padding:var(--s3);min-height:0}.s02 .s02-lu{grid-template-columns:repeat(2,minmax(0,1fr))}.s02 .s02-notes{padding:var(--s3)}}
@media (max-width:420px){.s02 .s02-slide{padding:var(--s2)}.s02 .s02-bar{padding:var(--s1) var(--s2)}.s02 .s02-notes{padding:var(--s2)}}
`;

const SK='abDeck02';
const st={i:0,notes:false};
try{const v=JSON.parse(sessionStorage.getItem(SK)||'null');if(v){st.i=Math.max(0,Math.min(15,+v.i||0));st.notes=!!v.notes}}catch(e){}
const save=()=>{try{sessionStorage.setItem(SK,JSON.stringify(st))}catch(e){}};

const secNo=id=>{try{const t=(typeof ALL!=='undefined'?ALL:[]).find(s=>s.id===id);return t?t.no:''}catch(e){return ''}};
function slideHTML(x,i,n){return `<section class="s02-slide" id="s02s${i}" data-i="${i}" role="group" aria-roledescription="${L('slide','slaidi')}" aria-label="${L('Slide','Slaidi')} ${i+1} ${L('of','kati ya')} ${n}"${i===st.i?'':' hidden'}>
 <div class="s02-grid${x.wide?' s02-wide':''}"><div><div class="s02-k">${i+1} / ${n} · ${L('about','takriban')} ${BUDGET[i]} ${L('seconds','sekunde')}</div><h2 class="s02-h">${x.h}</h2>
  <a class="s02-go" href="#${x.go}">${L('Open the full section','Fungua sehemu kamili')} ${E(secNo(x.go))} →</a></div>
 <div class="s02-v">${x.v}</div></div></section>`}

function render(s,p,pv,nx){const n=nums(),S=slides(n),lean=n.lean;
 const notes=S.map((x,i)=>`<div class="s02-note" data-i="${i}"${i===st.i?'':' hidden'}>${T(x.n[0],x.n[1])}</div>`).join('');
 return `<article class="ab-sec s02" aria-labelledby="h-s0-2"><style>${CSS}</style><div class="ab-wrap">
 <div class="ab-sec-no">${E(s.no)}</div><h1 id="h-s0-2">${E(s.title)}</h1>
 <p class="ab-summary">${L(`The whole case in sixteen slides and about ten minutes, for a founder presenting in a meeting or an investor reading alone. Each slide carries one headline, one figure and speaker notes in English and Kiswahili. Every number is read live from the financial model for the funding option selected, and every box price from the sourced item lists in section 3.5. Each number is marked as a model figure or a target: there are no sales results yet.`,`Hoja nzima kwa slaidi kumi na sita na takriban dakika kumi, kwa mwanzilishi anayewasilisha katika kikao au mwekezaji anayesoma peke yake. Kila slaidi ina kichwa kimoja, takwimu moja na maelezo ya mzungumzaji kwa Kiingereza na Kiswahili. Kila namba inasomwa moja kwa moja kutoka modeli ya fedha kwa chaguo la mtaji lililochaguliwa, na kila bei ya boksi kutoka orodha za vitu zenye vyanzo katika sehemu 3.5. Kila namba imewekewa alama kama takwimu ya modeli au lengo: bado hakuna matokeo ya mauzo.`)}</p>

 <figure class="ab-visual s02-deck" id="s02Deck" tabindex="-1" aria-label="${L('Presentation, sixteen slides','Wasilisho, slaidi kumi na sita')}">
  <div class="s02-bar">
   <button type="button" class="ab-btn" data-s02="prev" aria-controls="s02Stage">← ${L('Previous','Iliyotangulia')}</button>
   <span class="s02-ct" id="s02Ct" aria-live="polite">${st.i+1} / ${S.length}</span>
   <button type="button" class="ab-btn ab-pri" data-s02="next" aria-controls="s02Stage">${L('Next','Inayofuata')} →</button>
   <span class="s02-sp"></span>
   <div class="ab-seg" role="group" aria-label="${L('Funding option','Chaguo la mtaji')}"><button type="button" data-fund="flag" aria-pressed="${!lean}">${L('Flagship','Duka kuu')} 340M</button><button type="button" data-fund="lean" aria-pressed="${lean}">${L('Start small','Anza kidogo')} 150M</button></div>
   <button type="button" class="ab-btn" data-s02="notes" aria-expanded="${st.notes}" aria-controls="s02Notes">${L('Speaker notes','Maelezo ya mzungumzaji')}</button>
   <button type="button" class="ab-btn" data-s02="full">${L('Full screen','Skrini nzima')}</button>
  </div>
  <div id="s02Stage">${S.map((x,i)=>slideHTML(x,i,S.length)).join('')}</div>
  <div class="s02-notes" id="s02Notes"${st.notes?'':' hidden'}><h3>${L('Speaker notes','Maelezo ya mzungumzaji')}</h3>${notes}</div>
  <nav class="s02-dots" aria-label="${L('Go to slide','Nenda kwenye slaidi')}">${S.map((x,i)=>`<button type="button" data-s02go="${i}" aria-current="${i===st.i}" aria-label="${L('Slide','Slaidi')} ${i+1}">${i+1}</button>`).join('')}</nav>
 </figure>
 <p class="ab-mute" style="font-size:var(--fs-cap);margin-top:var(--s1)">${L('Keyboard: left and right arrows move between slides, Home and End jump to the first and last, N shows or hides the notes.','Kibodi: mishale ya kushoto na kulia inahamisha kati ya slaidi, Home na End zinaruka hadi ya kwanza na ya mwisho, N inaonyesha au kuficha maelezo.')}</p>

 <div class="ab-body">
  <section class="ab-block"><h2>${L('How to give this presentation','Jinsi ya kutoa wasilisho hili')}</h2>
   <p>${L('The order follows the questions an investor asks, and puts the facts before the story: what Afya is and one sourced price; the plan in five numbers and the ask; the problem; the households; the market as a funnel that ends in members; why now; the store, the boxes and the check; how membership works; the year-1 loss in plain words; growth; the downside case and the pre-sale gate; the five risks that belong to this business; and the ask in full.','Mpangilio unafuata maswali ambayo mwekezaji anauliza, na unaweka ukweli kabla ya simulizi: Afya ni nini na bei moja yenye chanzo; mpango kwa namba tano na ombi; tatizo; kaya; soko kama faneli inayoishia kwa wanachama; kwa nini sasa; duka, maboksi na kipimo; jinsi uanachama unavyofanya kazi; hasara ya mwaka wa 1 kwa maneno wazi; ukuaji; hali mbaya na kigezo cha mauzo ya awali; hatari tano zinazohusu biashara hii; na ombi kamili.')}</p>
   <p>${L('Each slide has a time budget; together they make ten minutes. The notes say what to stress and what to say about the source of each number. Every slide links to the section that holds the full working, so a question can be answered in depth without leaving the meeting.','Kila slaidi ina muda wake; kwa pamoja zinafanya dakika kumi. Maelezo yanasema nini cha kusisitiza na nini cha kusema kuhusu chanzo cha kila namba. Kila slaidi ina kiungo cha sehemu yenye hesabu kamili, hivyo swali linaweza kujibiwa kwa kina bila kuondoka kikaoni.')}</p>
   <p>${L('The funding switch above the slides changes every model number to the other option. Only one option is ever shown, so the two sets of figures are never mixed on one screen.','Kitufe cha chaguo la mtaji juu ya slaidi kinabadilisha kila namba ya modeli kwenda chaguo jingine. Chaguo moja tu linaonyeshwa kila wakati, hivyo seti mbili za takwimu hazichanganywi kamwe kwenye skrini moja.')}</p>
  </section>
  <section class="ab-block"><h2>${L('The sixteen slides','Slaidi kumi na sita')}</h2>
   <div class="ab-tw"><table class="ab-t s02-outline"><thead><tr><th>${L('Slide','Slaidi')}</th><th>${L('Headline','Kichwa')}</th><th>${L('Time','Muda')}</th></tr></thead><tbody>
   ${S.map((x,i)=>`<tr><td>${i+1}</td><td><a href="#s02Deck" data-s02go="${i}">${x.h.replace(/<span[^>]*data-num[^>]*>([^<]*)<\/span>/g,'$1')}</a></td><td class="ab-n">${BUDGET[i]} ${L('s','sek')}</td></tr>`).join('')}
   <tr><td></td><td><b>${L('Total','Jumla')}</b></td><td class="ab-n"><b>${Math.round(BUDGET.reduce((t,x)=>t+x,0)/60)} ${L('min','dak')}</b></td></tr></tbody></table></div>
   <details class="s02-all" style="margin-top:var(--s3)"><summary class="ab-mute" style="cursor:pointer">${L('Read all speaker notes as text','Soma maelezo yote ya mzungumzaji kama maandishi')}</summary>${S.map((x,i)=>`<h3>${i+1}. ${x.h.replace(/<span[^>]*data-num[^>]*>([^<]*)<\/span>/g,'$1')}</h3>${T(x.n[0],x.n[1])}`).join('')}</details>
  </section>
 </div>

 <section class="ab-block"><h2>${L('Key figures','Takwimu muhimu')}</h2>
  ${A().figsHTML([
   {v:`${N('k-seed',n.seed.amount,'tshM')}`,l:T('The seed asked for, in three tranches','Mtaji wa awali unaoombwa, kwa awamu tatu'),s:L(lean?'Start-small option':'Flagship option',lean?'Chaguo la kuanza kidogo':'Chaguo la duka kuu')},
   {v:`${n.be?`${L('Month','Mwezi')} ${N('k-be',n.be,'int')}`:L('Not in year 1','Si mwaka wa 1')} <span class="ab-est">${L('model','modeli')}</span>`,l:T('First month with a store operating profit','Mwezi wa kwanza wenye faida ya uendeshaji ya duka'),s:L('Financial model v1.2, base case','Modeli ya fedha v1.2, hali ya msingi')},
   {v:`${N('k-mem',n.mem12,'int')} <span class="ab-est">${L('model','modeli')}</span>`,l:T('Paying Afya Box members by month 12','Wanachama wa Afya Box wanaolipa ifikapo mwezi 12'),s:L('Deposits not yet converted are not counted','Amana ambazo bado hazijageuka uanachama hazihesabiwi')},
   {v:(()=>{const r=BP('mama-na-mtoto');return r?tsh(r.from):'—'})(),l:T('Mama na Mtoto a month, 12-month plan','Mama na Mtoto kwa mwezi, mpango wa miezi 12'),s:L('Sourced shelf prices, member pricing rule (section 3.5)','Bei za rafu zenye vyanzo, kanuni ya bei ya mwanachama (sehemu 3.5)')}])}
 </section>

 ${A().openHTML([
  L('All model figures are planning estimates. They are replaced by results as the pre-sale and the first months of trading report.','Takwimu zote za modeli ni makadirio ya mipango. Zitabadilishwa na matokeo kadri mauzo ya awali na miezi ya kwanza ya biashara inavyoripoti.'),
  L('The shares in the market funnel (about half of households with a monthly health need, about three in ten of those able to pay) are estimates, to be tested in 60 to 100 interviews in the store’s catchment.','Viwango vya faneli ya soko (takriban nusu ya kaya zenye hitaji la afya la kila mwezi, takriban tatu kati ya kumi ya hizo zinazoweza kulipa) ni makadirio, yatakayojaribiwa katika mahojiano 60 hadi 100 katika eneo la duka.'),
  L('The ownership split is illustrative and needs legal review; whether the investor share is the same in both options is still to be confirmed.','Mgawanyo wa umiliki ni wa mfano na unahitaji ukaguzi wa kisheria; kama sehemu ya mwekezaji ni ileile katika machaguo yote mawili bado inathibitishwa.'),
  L('Box prices follow Afya’s shelf prices, which are rebuilt every quarter; members see a new price before renewal.','Bei za maboksi zinafuata bei za rafu za Afya, ambazo zinahuishwa kila robo mwaka; wanachama wanaona bei mpya kabla ya kuhuisha.')])}

 <div id="abSrc">${A().sourcesHTML(SRC().map(x=>({t:x.t,u:x.u,chk:x.chk,lang:sw()?'sw':'en'})))}</div>
 ${A().pagerHTML(pv,nx)}
 </div></article>`}

/* ---------- navigation ---------- */
let off=null;
function go(i,focus){const sl=[...document.querySelectorAll('.s02 .s02-slide')];if(!sl.length)return;const n=sl.length;i=Math.max(0,Math.min(n-1,i));st.i=i;save();
 sl.forEach(x=>{x.hidden=+x.dataset.i!==i});
 document.querySelectorAll('.s02 .s02-note').forEach(x=>{x.hidden=+x.dataset.i!==i});
 document.querySelectorAll('.s02 .s02-dots [data-s02go]').forEach(b=>b.setAttribute('aria-current',String(+b.dataset.s02go===i)));
 const ct=document.getElementById('s02Ct');if(ct)ct.textContent=`${i+1} / ${n}`;
 const pv=document.querySelector('.s02 [data-s02="prev"]'),nx=document.querySelector('.s02 [data-s02="next"]');if(pv)pv.disabled=i===0;if(nx)nx.disabled=i===n-1;
 if(focus){const d=document.getElementById('s02Deck');if(d){d.focus({preventScroll:true});const r=d.getBoundingClientRect();if(r.top<0||r.top>innerHeight*0.5)d.scrollIntoView({block:'start'})}}}
function setNotes(on){st.notes=on;save();const el=document.getElementById('s02Notes'),b=document.querySelector('.s02 [data-s02="notes"]');if(el)el.hidden=!on;if(b)b.setAttribute('aria-expanded',String(on))}
function init(){const root=document.querySelector('.s02');if(!root)return;go(st.i,false);
 const onClick=e=>{const t=e.target.closest&&e.target.closest('[data-s02],[data-s02go]');if(!t||!root.contains(t))return;
  if(t.dataset.s02go!=null){e.preventDefault();go(+t.dataset.s02go,true);return}
  const a=t.dataset.s02;if(a==='prev')go(st.i-1);else if(a==='next')go(st.i+1);else if(a==='notes')setNotes(!st.notes);
  else if(a==='full'){const d=document.getElementById('s02Deck');try{if(document.fullscreenElement)document.exitFullscreen();else if(d&&d.requestFullscreen)d.requestFullscreen()}catch(err){}}};
 const onKey=e=>{if(e.altKey||e.ctrlKey||e.metaKey)return;const tg=e.target,tn=tg&&tg.tagName;if(tn==='INPUT'||tn==='TEXTAREA'||tn==='SELECT'||(tg&&tg.isContentEditable))return;
  const inDeck=!!(tg&&tg.closest&&tg.closest('#s02Deck'));const k=e.key;
  if(k===' '&&(tn==='BUTTON'||tn==='A'||tn==='SUMMARY'))return;
  if(k==='ArrowRight'||(inDeck&&(k==='PageDown'||k===' '))){e.preventDefault();go(st.i+1)}
  else if(k==='ArrowLeft'||(inDeck&&k==='PageUp')){e.preventDefault();go(st.i-1)}
  else if(k==='Home'&&inDeck){e.preventDefault();go(0)}else if(k==='End'&&inDeck){e.preventDefault();go(15)}
  else if(k==='n'||k==='N'){setNotes(!st.notes)}};
 if(off)off();root.addEventListener('click',onClick);document.addEventListener('keydown',onKey);
 off=()=>{root.removeEventListener('click',onClick);document.removeEventListener('keydown',onKey);off=null};
 addEventListener('afya:leave',()=>{if(off)off()},{once:true})}

window.SECTIONS['s0-2']={render,init,v2:true};
})();
